
import os
import pandas as pd
from urllib.parse import quote_plus
from pymongo import MongoClient

# MongoDB Atlas credentials
username = quote_plus("jamunajai02_db_user")
password = quote_plus(os.getenv("MONGODB_PASSWORD"))

if not password:
    raise ValueError("Set MONGODB_PASSWORD in your terminal first.")

# Connect to MongoDB Atlas
uri = (
    f"mongodb+srv://{username}:{password}"
    "@ipl.1smt2su.mongodb.net/?retryWrites=true&w=majority"
)

client = MongoClient(uri)
db = client["IPL_StratX"]

# Read the association rules generated by IPL StratX
file_path = r"D:\IPL\outputs\IPL_StratX_association_rules.csv"
df = pd.read_csv(file_path)

# Convert CSV rows into MongoDB documents
records = df.where(pd.notnull(df), None).to_dict("records")

# Upload data to Atlas
collection = db["association_rules"]
collection.delete_many({})

if records:
    collection.insert_many(records)

print("Association rules uploaded successfully!")
print("Total documents:", collection.count_documents({}))

client.close()
